<?php require_once dirname(__DIR__).'/core/bootstrap.php';require_admin();$title='مدیریت تبلیغات';
function save_ad_image(array $f): string { $root=dirname(__DIR__); if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new Exception('تصویر لازم است.'); if(($f['size']??0)>5*1024*1024)throw new Exception('حداکثر حجم ۵ مگابایت است.'); $fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($map[$mime]))throw new Exception('فرمت تصویر مجاز نیست.');$dir=$root.'/uploads/ads';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(16)).'.'.$map[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new Exception('ذخیره تصویر ناموفق بود.');return 'uploads/ads/'.$name; }
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='save'){try{$id=(int)($_POST['id']??0);$titlev=trim($_POST['title']??'');$target=trim($_POST['target_url']??'');if($target!==''&&!validate_http_url($target))throw new Exception('لینک مقصد معتبر نیست.');$seconds=max(0,min(60,(int)($_POST['display_seconds']??4)));$priority=(int)($_POST['priority']??0);$active=isset($_POST['active'])?1:0;$image='';if($id){$st=$pdo->prepare('SELECT image_path FROM ads WHERE id=?');$st->execute([$id]);$image=(string)($st->fetchColumn()?:'');}if(!empty($_FILES['image']['name']))$image=save_ad_image($_FILES['image']);if(!$titlev||!$image)throw new Exception('عنوان و تصویر الزامی است.');if($id)$pdo->prepare("UPDATE ads SET title=?,image_path=?,target_url=?,display_seconds=?,priority=?,active=?,updated_at=NOW() WHERE id=?")->execute([$titlev,$image,$target?:null,$seconds,$priority,$active,$id]);else$pdo->prepare("INSERT INTO ads(title,image_path,target_url,placement,plan,display_seconds,priority,active,created_at,updated_at) VALUES(?,?,?,'pre_connect','free',?,?,?,NOW(),NOW())")->execute([$titlev,$image,$target?:null,$seconds,$priority,$active]);flash('success','تبلیغ ذخیره شد.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/ads.php');}
if($a==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare('SELECT image_path FROM ads WHERE id=?');$st->execute([$id]);$img=$st->fetchColumn();$pdo->prepare('DELETE FROM ads WHERE id=?')->execute([$id]);if($img){$p=dirname(__DIR__).'/'.$img;if(is_file($p))@unlink($p);}flash('success','حذف شد.');redirect('/admin/ads.php');}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM ads WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$list=$pdo->query('SELECT * FROM ads ORDER BY priority DESC,id DESC')->fetchAll();require __DIR__.'/_header.php';?><div class="card"><h3><?=$edit?'ویرایش تبلیغ':'تبلیغ جدید برای قبل از اتصال پلن رایگان'?></h3><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><div class="formgrid"><div><label>عنوان</label><input name="title" value="<?=e($edit['title']??'')?>" required></div><div><label>لینک مقصد</label><input name="target_url" type="url" value="<?=e($edit['target_url']??'')?>" placeholder="https://..."></div><div><label>زمان نمایش (ثانیه)</label><input name="display_seconds" type="number" min="0" max="60" value="<?=e((string)($edit['display_seconds']??4))?>"></div><div><label>اولویت</label><input name="priority" type="number" value="<?=e((string)($edit['priority']??0))?>"></div><div class="full"><label>تصویر (JPG/PNG/WebP/GIF، حداکثر ۵MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif" <?=$edit?'':'required'?>></div><div><label><input style="width:auto" type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> فعال</label></div><div><button>ذخیره تبلیغ</button></div></div></form></div><div class="card" style="margin-top:14px"><h3>تبلیغات</h3><table><thead><tr><th>تصویر</th><th>عنوان</th><th>زمان</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($list as $a):?><tr><td><img class="adimg" src="<?=e(app_path('/'.$a['image_path']))?>" alt=""></td><td><?=e($a['title'])?></td><td><?=e((string)$a['display_seconds'])?> ثانیه</td><td><span class="badge <?=$a['active']?'good':''?>"><?=$a['active']?'فعال':'خاموش'?></span></td><td><div class="actions"><a class="btn secondary" href="?edit=<?=$a['id']?>">ویرایش</a><form method="post" onsubmit="return confirm('حذف شود؟')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn bad">حذف</button></form></div></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/_footer.php';
